sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float copies;
uniform float2 center;
uniform float zoomStep;
uniform float rotStep;
uniform float decay;
layout(color) uniform half4 tint;
uniform float tintAmount;
uniform float combine;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float4 texT(float2 p) {
    return float4(image.eval(p));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float2 rot2(float2 p, float a) {
    float s = sin(a);
    float c = cos(a);
    return float2(p.x * c - p.y * s, p.x * s + p.y * c);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 ctr = center * size;
    float4 acc = float4(0.0);
    for (int i = 0; i < 24; i++) {
        float k = 23.0 - float(i);
        if (k >= copies) continue;
        float2 q = ctr + rot2(coord - ctr, -radians(rotStep) * k) / pow(zoomStep, k);
        float4 s4 = texT(q) * pow(1.0 - decay, k);
        float mixAmt = tintAmount * k / max(copies, 1.0);
        s4 = float4(mix(s4.rgb, float3(tint.rgb) * s4.a, mixAmt), s4.a);
        if (combine < 0.5) acc = s4 + acc * (1.0 - s4.a);
        else if (combine < 1.5) acc += s4;
        else if (combine < 2.5) acc = acc + s4 - acc * s4;
        else acc = max(acc, s4);
    }
    return fin(c, acc, opacity);
}
